{"path": "zebra_puzzle.py", "content": "from itertools import permutations


def _solve():
    houses = range(5)
    first, middle = 0, 2

    def right_of(a, b):
        return a == b + 1

    def next_to(a, b):
        return abs(a - b) == 1

    for red, green, ivory, yellow, blue in permutations(houses):
        if not right_of(green, ivory):
            continue
        for english, spaniard, ukrainian, norwegian, japanese in permutations(houses):
            if english != red or norwegian != first or not next_to(norwegian, blue):
                continue
            for coffee, tea, milk, orange_juice, water in permutations(houses):
                if coffee != green or tea != ukrainian or milk != middle:
                    continue
                for dancing, painting, reading, football, chess in permutations(houses):
                    if (painting != yellow or football != orange_juice
                            or chess != japanese):
                        continue
                    for dog, snail, fox, horse, zebra in permutations(houses):
                        if (dog != spaniard or snail != dancing
                                or not next_to(reading, fox)
                                or not next_to(painting, horse)):
                            continue
                        names = {
                            english: 'Englishman',
                            spaniard: 'Spaniard',
                            ukrainian: 'Ukrainian',
                            norwegian: 'Norwegian',
                            japanese: 'Japanese',
                        }
                        return names[water], names[zebra]
    return None


_WATER, _ZEBRA = _solve()


def drinks_water():
    return _WATER


def owns_zebra():
    return _ZEBRA
"}

